    h = hyps.get(hid)
    ps = [q for q in (h or {}).get("parent_hypothesis_ids", []) if q in hyps and q not in seen]
    dep[hid] = 1 if not ps or h.get("lineage_op") == "root" else 1 + max(max_depth(q, seen | {hid}) for q in ps)
    return dep[hid]
