    ss = [matstatus.get(i, "missing") for i in ids]
    if any(s == "verified" for s in ss): return "verified"
    if any(s == "partially_verified" for s in ss): return "partial"
    return "none" if not ids else "other"
cell = collections.Counter(); critc = collections.Counter()
for r in rows:
