    same = r["session_id"] == h.get("session_id"); d = dep[t] >= 2
    k = (same, d, tier(r)); cell[k] += 1; critc[k] += crit(r["verdict"])
for (same, d, t), n in sorted(cell.items()):
    print(("SAME " if same else "CROSS"), "d>=1" if d else "d0   ", t, f"n={n:4d}", f"crit={critc[(same,d,t)]:3d}", f"rate={100*critc[(same,d,t)]/n:.1f}%")
def lp(x, r1, c1, n):
    return (lgamma(r1+1)+lgamma(n-r1+1)+lgamma(c1+1)+lgamma(n-c1+1)-lgamma(n+1)-lgamma(x+1)-lgamma(r1-x+1)-lgamma(c1-x+1)-lgamma(n-r1-c1+x+1))
def fisher(a, b, c, d):
    n = a+b+c+d; r1, c1 = a+b, a+c; lo, hi = max(0, r1+c1-n), min(r1, c1); obs = lp(a, r1, c1, n)
    return sum(exp(lp(x, r1, c1, n)) for x in range(lo, hi+1) if lp(x, r1, c1, n) <= obs + 1e-12)
def cell2(same, d, t): return critc[(same, d, t)], cell[(same, d, t)]
for tier_name in ("verified", "partial", "none"):
    a, n = cell2(True, True, tier_name); c, m = cell2(False, True, tier_name)
    print(f"depth>=1 {tier_name}: SAME {a}/{n} vs CROSS {c}/{m} Fisher_p={fisher(a, n-a, c, m-c):.3g}")
same1 = sum(critc[(True, d, t)] for d in (True, False) for t in ("verified","partial","none","other"))
sameN = sum(cell[(True, d, t)] for d in (True, False) for t in ("verified","partial","none","other"))
sd1 = sum(crit(r["verdict"]) for r in rows if dep[r["target_hypothesis_id"]] >= 2 and rows and r["session_id"] == hyps[r["target_hypothesis_id"]]["session_id"])
sd1n = sum(1 for r in rows if dep[r["target_hypothesis_id"]] >= 2 and r["session_id"] == hyps[r["target_hypothesis_id"]]["session_id"])
xd1 = sum(crit(r["verdict"]) for r in rows if dep[r["target_hypothesis_id"]] >= 2 and r["session_id"] != hyps[r["target_hypothesis_id"]]["session_id"])
xd1n = sum(1 for r in rows if dep[r["target_hypothesis_id"]] >= 2 and r["session_id"] != hyps[r["target_hypothesis_id"]]["session_id"])
print(f"SAME all n={sameN} crit={same1} ({100*same1/sameN:.1f}%)")
print(f"SAME d>=1 n={sd1n} crit={sd1} ({100*sd1/sd1n:.1f}%); CROSS d>=1 n={xd1n} crit={xd1} ({100*xd1/xd1n:.1f}%)")

